// Try connecting with a raw TCP + PostgreSQL startup message to see what Railway responds with
const net = require\('net'\);
const socket = new net.Socket\(\);
socket.setTimeout\(8000\);
let received = Buffer.alloc\(0\);

socket.connect\(55141, 'mainline.proxy.rlwy.net', \(\) => {
  console.log\('TCP connected, sending SSLRequest...'\);
  // PostgreSQL SSL request message: length=8, code=80877103
  const sslRequest = Buffer.from\([0x00, 0x00, 0x00, 0x08, 0x04, 0xd2, 0x16, 0x2f]\);
  socket.write\(sslRequest\);
}\);

socket.on\('data', d => {
  received = Buffer.concat\([received, d]\);
  console.log\('Server response \(hex\):', d.toString\('hex'\), '\(ascii\):', d.toString\('ascii'\).replace\(/[^\\\\x20-\\\\x7E]/g,'?'\)\);
  if \(received.length >= 1\) {
    socket.destroy\(\);
  }
}\);

socket.on\('error', e => console.error\('Error:', e.message\)\);
socket.on\('close', \(\) => console.log\('Connection closed'\)\);
socket.on\('timeout', \(\) => { console.log\('Timeout'\); socket.destroy\(\); }\);
